 suspend fun catalog():JSONObject {val rows=AnimeSeason056.load(2026,3);check(rows.isNotEmpty());return JSONObject().put("quarter", "2026秋").put("works",rows.size).put("scheduled",rows.count{it.weekday>0}).put("chineseEnriched",rows.count{it.work.title!=it.work.original}).put("samples",JSONArray(rows.take(8).map{JSONObject().put("title",it.work.title).put("weekday",it.weekday).put("time",it.time)}))}
 suspend fun playGiri(i:Instrumentation,m:PtvModel):JSONObject {val rules=AnimeRules056(i.targetContext);val site=rules.sites().first{it.key=="kazumi_girigirilove"};val search=withTimeout(22000){rules.search(site,"间谍过家家")};val row=search.first();val detail=withTimeout(22000){rules.detail(site,row)};val road=detail.roads.first{it.episodes.isNotEmpty()};val episode=road.episodes.first();val candidate=withTimeout(40000){m.sites.probe(site,road,episode)};i.runOnMainSync{m.current=Work("qa056-giri","间谍过家家","tv",provider="site_${site.key}");m.select(candidate,0);m.player.volume=0f};UiQa050.await(45000){var ok=false;i.runOnMainSync{ok=m.hasRenderedFrame()&&m.player.currentPosition>2000};ok};var width=0;var height=0;var position=0L;i.runOnMainSync{width=m.player.videoSize.width;height=m.player.videoSize.height;position=m.player.currentPosition};val out=JSONObject().put("site",site.key).put("title",row.title).put("episode",episode.name).put("mediaHost",android.net.Uri.parse(candidate.episode.url).host).put("mime",candidate.mimeType).put("width",width).put("height",height).put("positionMs",position);UiQa050.shot(i,"qa056-anime-real-playback.png");i.runOnMainSync{m.stop()};return out}
 suspend fun sources(i:Instrumentation,m:PtvModel):JSONObject=coroutineScope {val rules=AnimeRules056(i.targetContext);val gate=Semaphore(3);val hits=mutableListOf<Pair<Site,Vod>>();val checks=rules.sites().map{s->async(Dispatchers.IO){gate.withPermit{val out=JSONObject().put("site",s.key);try{val rows=withTimeout(22000){rules.search(s,"间谍过家家")};out.put("searchResults",rows.size);synchronized(hits){rows.firstOrNull()?.let{hits+=s to it}}}catch(e:Exception){out.put("error",e.message?.take(120))};out}}}.awaitAll();val output=JSONObject().put("checks",JSONArray(checks));var played=false
  val attempts=JSONArray();for((site,vod) in hits.take(8)){val a=JSONObject().put("site",site.key).put("title",vod.title);try{val detail=withTimeout(20000){rules.detail(site,vod)};a.put("episodes",detail.roads.sumOf{it.episodes.size});val road=detail.roads.first();val candidate=withTimeout(40000){m.sites.probe(site,road,road.episodes.first())};i.runOnMainSync{m.current=Work("qa056-anime",vod.title,"tv",provider="site_"+site.key);m.select(candidate,0);m.player.volume=0f};UiQa050.await(35000){var ok=false;i.runOnMainSync{ok=m.hasRenderedFrame()&&m.player.currentPosition>2000};ok};i.runOnMainSync{a.put("firstFrame",true).put("positionMs",m.player.currentPosition).put("width",m.player.videoSize.width).put("height",m.player.videoSize.height);m.stop()};played=true;attempts.put(a);break}catch(e:Exception){a.put("error",e.message?.take(120));i.runOnMainSync{m.stop()};attempts.put(a)}}
